<script setup lang="ts">
import "./pms-source.css";
import "./pms-layout.css";
import {ref,onMounted} from 'vue';const props=defineProps<{csrf?:string}>();const token=window.location.pathname.split('/').pop(),invitation=ref<any>(null),busy=ref(false),error=ref(''),form=ref({name:'',password:'',password_confirmation:''});async function send(){busy.value=true;try{const r=await fetch('/pms/invitation/'+token,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:JSON.stringify(form.value)});const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message);window.location.assign(d.redirect_url);}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}onMounted(async()=>{try{const r=await fetch('/pms/invitation/'+token,{headers:{Accept:'application/json'}});const d=await r.json();if(!r.ok)throw Error(d.message);invitation.value=d.data.invitation;form.value.name=invitation.value.invitee_name||'';}catch(e){error.value=(e as Error).message;}});
</script><template><section class="pms-workspace"><div class="card p-4" style="max-width:600px;margin:40px auto;grid-column:1/-1;width:95%"><h2>Accept your invitation</h2><p v-if="error" class="notice admin-error">{{error}}</p><form v-if="invitation" @submit.prevent="send" class="pms-task-edit mt-3"><p>You are invited as {{invitation.assigned_role?.role_name||'a team member'}}.</p><p>{{invitation.invitee_email}}</p><label>Name<input v-model="form.name" required maxlength="255"></label><label>Password<input v-model="form.password" type="password" required minlength="8" autocomplete="new-password"></label><small>Use at least eight characters, including letters and numbers.</small><label>Confirm password<input v-model="form.password_confirmation" type="password" required autocomplete="new-password"></label><button class="button primary" :disabled="busy">{{busy?'Creating account...':'Accept and create account'}}</button></form></div></section></template>